"""Generate document and numeric explorer from saved results. No image interpretation."""
from pathlib import Path
import base64,csv,gzip,html,json,math
import pandas as pd
import mistune

ROOT=Path(__file__).resolve().parents[1]
CSS='''body{margin:0;background:#f5f6f8;color:#192333;font:16px/1.8 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1100px;margin:30px auto;background:white;padding:38px 50px;box-shadow:0 2px 16px #18294412}h1{font-size:31px;line-height:1.4}h2{margin-top:2.2em;padding-top:12px;border-top:2px solid #dfe5ec}h3{margin-top:1.8em}table{border-collapse:collapse;width:100%;font-size:14px;margin:18px 0;display:block;overflow:auto}td,th{padding:9px 12px;border-bottom:1px solid #dce2e8;text-align:left}th{background:#edf1f5}tr:nth-child(even){background:#f9fafc}a{color:#174f8c}pre{padding:17px;background:#eef2f6;overflow:auto;line-height:1.55}code{font-family:ui-monospace,monospace;font-size:.88em;overflow-wrap:anywhere}img{max-width:100%;height:auto}blockquote{border-left:4px solid #597896;padding-left:20px;margin-left:0;color:#354960}nav{padding:12px;background:#eef2f6}select,input,button{font:inherit;padding:6px;max-width:100%}.note{color:#536477;font-size:14px}.grid{display:flex;gap:18px;flex-wrap:wrap}.box{border:1px solid #ccd5e0;padding:15px;flex:1;min-width:250px}.metric{font-size:22px;font-weight:600}.badge{display:inline-block;background:#eef2f6;padding:3px 10px;margin:3px}@media(max-width:700px){main{padding:20px;margin:0}h1{font-size:25px}td,th{padding:5px;font-size:12px}}'''
MD=mistune.create_markdown(plugins=['table'])

def wrap(title,body):return '<!DOCTYPE html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+html.escape(title)+'</title><style>'+CSS+'</style><main>'+body+'</main></html>'
def embed(body,base):
    import re
    def repl(m):
        p=base/m.group(1)
        if not p.exists():return m.group(0)
        return 'src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'"'
    return re.sub(r'src="([^"#]+\.png)"',repl,body)
def run():
    report=ROOT/'report';out=ROOT/'results/final_run'
    for name in ['REPORT_ZH']:
        b=MD((report/(name+'.md')).read_text());(report/(name+'.html')).write_text(wrap('分簇收束与分析准备',b),encoding='utf-8');(ROOT/'clustering_release_report_20260920.html').write_text(wrap('分簇收束与分析准备',embed(b,report)),encoding='utf-8')
    start='''<h1>分簇收束与分析准备</h1><p class="badge">RC1-20260920</p><p>主候选：同有效总点数、top/bottom循环编号、最大端点9°、完整链接。原坐标不改；6/12°敏感性；局部确认不自动合簇。</p><div class="grid"><div class="box"><h2>阅读</h2><p><a href="report/REPORT_ZH.html">完整中文报告与图表</a></p><p><a href="report/RESULTS_BROWSER.html">239单元数值成员与逐点对应浏览器</a></p><p><a href="NEW_DATA.md">新增真人与人工对应接入说明</a></p><p><a href="PAPER_PLAN.md">论文图表提纲</a></p></div><div class="box"><h2>结果</h2><p><a href="results/final_run/memberships.csv">逐份成员CSV</a></p><p><a href="results/final_run/endpoint_correspondences.csv.gz">全部端点对应CSV.GZ</a></p><p><a href="results/final_run/minimal_local_check.csv">10项最小本地补查清单</a></p><p><a href="results/final_run/review_backlog.csv">全部477项数值告警</a></p><p><a href="REPRODUCIBILITY.json">重跑与输入校验</a></p></div></div><h2>重跑</h2><pre>python -B code/run_all.py --root . --config config.json --out results/my_rerun</pre><p>当前资料为历史探索，不是新增真人验证。A–D为历史偏离分位档，不是心理类型；簇不代表不同物理房间；没有冻结统一停止人数。本轮未重新解释原图。</p>'''
    (ROOT/'00_START_HERE.html').write_text(wrap('开始阅读',start),encoding='utf-8')
    cache=json.loads((out/'cache.json').read_text());mem=pd.read_csv(out/'memberships.csv');groups=[]
    for key,g in cache.items():
        rows=mem[(mem.image_id==key.split('|')[0])&(mem.condition==key.split('|')[1])];views={}
        for (method,cut),d in rows.groupby(['metric','cut']):views[method+'_'+str(int(cut))]={r.id:int(r.cluster) for r in d.itertuples()}
        groups.append(dict(key=key,code=g['code'],condition=key.split('|')[1],Nrecord=g['N_record'],ids=g['ids'],workers=g['workers'],counts=g['counts'],views=views))
    ep=pd.read_csv(out/'endpoint_correspondences.csv.gz');ep=ep[ep.metric.eq('split_cyclic')];pairs={}
    for (a,b),d in ep.groupby(['id_a','id_b'],sort=False):pairs[a+'|'+b]=[[0 if r.role=='top' else 1,int(r.point_a),int(r.point_b),round(float(r.error_deg),10)] for r in d.itertuples()]
    payload=json.dumps(dict(groups=groups,pairs=pairs),ensure_ascii=False,separators=(',',':')).replace('</',r'<\/')
    body='''<h1>239单元数值浏览器</h1><p>仅显示已计算成员和原点号，不提供新的物理/视觉判断。近对与完整分区不同；部分人工锚点未自动覆盖结果。主对应表保留10位数值精度，下载CSV为完整结果。</p><div class="grid"><label>图像/条件<br><input id="filter" placeholder="搜索代码"><br><select id="unit"></select></label><label>分组视图<br><select id="view"></select></label></div><p id="scope"></p><div id="members"></div><h2>两名真人的主方案对应</h2><label>A <select id="a"></select></label> <label>B <select id="b"></select></label><p id="distance"></p><div id="points"></div><p class="note">181是签名不相容占位值；无同角色/同点数对应时不显示虚构端点偏差。当前显示的相近不代表正确或结构相同。整数簇号也不能跨版本当永久模式ID。</p>'''
    js='''const DATA=PAYLOAD;const $=id=>document.getElementById(id);let current;function options(el,items){el.innerHTML='';for(let [v,t] of items){let op=document.createElement('option');op.value=v;op.textContent=t;el.appendChild(op)}}function filter(){let q=$('filter').value.toLowerCase();options($('unit'),DATA.groups.map((g,i)=>[i,g.code+' / '+g.condition]).filter(x=>x[1].toLowerCase().includes(q)));load()}function load(){let i=$('unit').value;if(i==='')return;current=DATA.groups[+i];options($('view'),Object.keys(current.views).map(v=>[v,v]));$('view').value='split_cyclic_9';options($('a'),current.ids.map((id,i)=>[id,current.workers[i]+' / '+id]));options($('b'),current.ids.map((id,i)=>[id,current.workers[i]+' / '+id]));if(current.ids.length>1)$('b').selectedIndex=1;render()}function render(){if(!current)return;let v=current.views[$('view').value]||{};let co={};for(let id in v)co[v[id]]=(co[v[id]]||0)+1;$('scope').textContent='保留响应 '+current.Nrecord+'；此视图可计算 '+Object.keys(v).length+'；组数 '+Object.keys(co).length+'；人数分布 '+Object.values(co).sort((a,b)=>b-a).join(' / ');let t='<table><thead><tr><th>人员</th><th>canonical ID</th><th>有效点数</th><th>簇</th><th>组内人数</th></tr></thead><tbody>';current.ids.forEach((id,i)=>{t+='<tr><td>'+current.workers[i]+'</td><td><code>'+id+'</code></td><td>'+current.counts[i]+'</td><td>'+(v[id]??'不可计算')+'</td><td>'+(co[v[id]]??'—')+'</td></tr>'});$('members').innerHTML=t+'</tbody></table>';pair()}function pair(){let a=$('a').value,b=$('b').value,v=current.views[$('view').value]||{};if(a===b){$('distance').textContent='请选择两个不同真人';$('points').innerHTML='';return}let p=DATA.pairs[a+'|'+b],swap=false;if(!p){p=DATA.pairs[b+'|'+a];swap=true}let same=v[a]!==undefined&&v[b]!==undefined?(v[a]===v[b]?'同组':'不同组'):'此视图不可比较';if(!p){$('distance').textContent='没有同签名端点对应；当前分组：'+same;$('points').innerHTML='';return}let mx=Math.max(...p.map(x=>x[3]));$('distance').textContent='主方案最大端点误差 '+mx.toFixed(6)+'°；当前所选分区 '+same;let t='<table><thead><tr><th>角色</th><th>A原点号</th><th>B原点号</th><th>误差（°）</th></tr></thead><tbody>';for(let r of p){t+='<tr><td>'+(r[0]?'bottom':'top')+'</td><td>'+r[swap?2:1]+'</td><td>'+r[swap?1:2]+'</td><td>'+r[3].toFixed(6)+'</td></tr>'}$('points').innerHTML=t+'</tbody></table>'} $('filter').oninput=filter;$('unit').onchange=load;$('view').onchange=render;$('a').onchange=pair;$('b').onchange=pair;filter();'''.replace('PAYLOAD',payload)
    (report/'RESULTS_BROWSER.html').write_text(wrap('239单元数值浏览器',body+'<script>'+js+'</script>'),encoding='utf-8')
if __name__=='__main__':run()
